57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Pragmatic syntactic check for an email address: a non-empty local part, a single {@code @}, and a
65	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
69	
70	    private final ClinicService clinicService;
