150	        Owner owner = this.clinicService.findOwnerById(ownerId);
151	        if (owner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        this.clinicService.deleteOwner(owner);
155	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        HttpHeaders headers = new HttpHeaders();
166	        Pet pet = petMapper.toPet(petFieldsDto);
167	        owner.setId(ownerId);
168	        pet.setOwner(owner);
169	        pet.getType().setName(null);
170	        this.clinicService.savePet(pet);
171	        PetDto petDto = petMapper.toPetDto(pet);
172	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
173	            .buildAndExpand(pet.getId()).toUri());
174	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
175	    }
