200	        pet.setId(petId);
201	        visit.setPet(pet);
202	        this.clinicService.saveVisit(visit);
203	        VisitDto visitDto = visitMapper.toVisitDto(visit);
204	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
205	            .buildAndExpand(visit.getId()).toUri());
