209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Override
212	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
213	        Owner owner = this.clinicService.findOwnerById(ownerId);
214	        if (owner != null) {
215	            Pet pet = owner.getPet(petId);
216	            if (pet != null) {
217	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
218	            }
219	        }
220	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	    }
222	
223	    /**
224	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
225	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
226	     *
227	     * @param fields the submitted owner fields
228	     * @throws RequiredFieldsMissingException if any of firstName, lastName, address, city or telephone is
229	     *                                        {@code null} or blank
230	     */
231	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
232	        List<String> missing = new ArrayList<>();
233	        if (isBlank(fields.getFirstName())) {
234	            missing.add("firstName");
235	        }
236	        if (isBlank(fields.getLastName())) {
237	            missing.add("lastName");
238	        }
239	        if (isBlank(fields.getAddress())) {
240	            missing.add("address");
241	        }
242	        if (isBlank(fields.getCity())) {
243	            missing.add("city");
244	        }
245	        if (isBlank(fields.getTelephone())) {
246	            missing.add("telephone");
247	        }
248	        if (!missing.isEmpty()) {
249	            throw new RequiredFieldsMissingException(missing);
250	        }
251	    }
252	
253	    private boolean isBlank(String value) {
254	        return value == null || value.isBlank();
255	    }
256	
257	    /**
258	     * Normalizes a submitted telephone number by removing every non-digit character and requiring the
259	     * result to be exactly ten digits, which becomes the stored and returned value.
260	     *
261	     * @param telephone the raw telephone value from the request
262	     * @return the 10-digit, digits-only telephone
263	     * @throws InvalidTelephoneException if the stripped value is not exactly ten digits
264	     */
